const q = $input.first().json.query || {};

if (q.error || !q.code) {
  return [{ json: {
    ok: false,
    titulo: 'A Meta não devolveu o código',
    detalhe: q.error_description || q.error || 'A URL de retorno veio sem o parâmetro code.'
  } }];
}

if (!$env.META_APP_ID || !$env.META_APP_SECRET) {
  return [{ json: {
    ok: false,
    titulo: 'Faltam META_APP_ID e META_APP_SECRET',
    detalhe: 'Preencha os dois na aba Environment do app n8n no Easypanel e clique em Deploy.'
  } }];
}

return [{ json: { ok: true, code: q.code } }];

const r = $input.first().json || {};

if (!r.access_token) {
  const e = (r.error && (r.error.message || r.error.error_user_msg)) || JSON.stringify(r).slice(0, 400);
  return [{ json: {
    html: `<!doctype html><meta charset="utf-8"><title>Deu erro</title><body style="font-family:system-ui;max-width:680px;margin:60px auto;padding:0 20px;line-height:1.6"><h2>A troca falhou</h2><p>${e}</p><p>O código da Meta vale menos de um minuto. Se demorou, abra a URL de login de novo.</p></body>`
  } }];
}

const tipo = r.token_type || 'bearer';
const expira = r.expires_in ? Math.round(r.expires_in / 86400) + ' dias' : 'não expira';

return [{ json: {
  html: `<!doctype html><meta charset="utf-8"><title>Token do Instagram</title><body style="font-family:system-ui;max-width:760px;margin:60px auto;padding:0 20px;line-height:1.6">` +
    `<h2>Token gerado</h2>` +
    `<p>Validade: <strong>${expira}</strong> · tipo ${tipo}</p>` +
    `<p>Copie o valor abaixo e cole em <code>IG_TOKEN</code>, na aba <em>Environment</em> do app <strong>n8n</strong> no Easypanel. Depois clique em Deploy.</p>` +
    `<textarea readonly style="width:100%;height:160px;font-family:ui-monospace,monospace;font-size:13px;padding:12px">${r.access_token}</textarea>` +
    `<p style="color:#b00">Depois de copiar, <strong>desative este workflow</strong> no n8n.</p>` +
    `</body>`
} }];

const d = $input.first().json;
return [{ json: {
  html: `<!doctype html><meta charset="utf-8"><title>${d.titulo}</title><body style="font-family:system-ui;max-width:680px;margin:60px auto;padding:0 20px;line-height:1.6"><h2>${d.titulo}</h2><p>${d.detalhe}</p></body>`
} }];
